css:
:root{
--tk-accent:#51a2ff;--tk-in:#60a5fa;--tk-cr:#2dd4bf;--tk-cw:#a78bfa;--tk-out:#f472b6;
--tk-ok:#4ade80;--tk-warn:#d4d4d8;--tk-bad:#ff6467;
--tk-fg:color-mix(in srgb,var(--foreground) 88%,transparent);--tk-strong:var(--foreground);
--tk-muted:var(--muted-foreground);--tk-track:color-mix(in srgb,var(--foreground) 15%,transparent);
--tk-line:color-mix(in srgb,var(--border) 65%,transparent);--tk-tick:color-mix(in srgb,var(--foreground) 70%,transparent);
--tk-pillc:color-mix(in srgb,var(--tk-warn) 20%,transparent);
--tk-tone:var(--tk-ok);}
:root:not(.dark){
--tk-accent:#1b4ed8;--tk-in:#2563eb;--tk-cr:#0d9488;--tk-cw:#7c3aed;--tk-out:#db2777;
--tk-ok:#15803d;--tk-warn:#3f3f46;--tk-bad:#c10007;
--tk-pillc:color-mix(in srgb,var(--tk-warn) 16%,transparent);}
[data-chat-column][data-tokpanel="1"]{--tk-tone:var(--tk-ok)}
[data-chat-column][data-tokpanel="1"][data-tokpanel-tone="warn"]{--tk-tone:var(--tk-warn)}
[data-chat-column][data-tokpanel="1"][data-tokpanel-tone="error"]{--tk-tone:var(--tk-bad)}

[data-chat-column][data-tokpanel="1"] [data-thread-details-panel="inline"]{display:flex;flex-direction:column;gap:8px}
[data-chat-column][data-tokpanel="1"] [data-thread-details-panel="inline"]>[data-thread-details-card]{flex:0 1 auto;min-height:0}
[data-chat-column][data-tokpanel="1"] [data-thread-details-panel="inline"]:has([data-tokpanel-card],[data-tokpanel-agents][data-open="1"]){overflow:hidden auto;overscroll-behavior:contain;scrollbar-width:none}
[data-chat-column][data-tokpanel="1"] [data-thread-details-panel="inline"]:has([data-tokpanel-card],[data-tokpanel-agents][data-open="1"])>[data-thread-details-card]{flex:none}

[data-chat-column][data-tokpanel="1"] :is([data-tokpanel-card],[data-tokpanel-agents]){display:flex!important;content-visibility:visible!important;flex-direction:column;flex:none;box-sizing:border-box;padding:8px 12px;border-radius:16px;font-size:12px;line-height:18px;font-variant-numeric:tabular-nums;letter-spacing:0;pointer-events:auto;color:var(--tk-fg);background-color:color-mix(in srgb,var(--popover) 18%,color-mix(in srgb,var(--popover) var(--glass-opacity,80%),transparent));-webkit-backdrop-filter:blur(var(--glass-blur,12px)) saturate(var(--glass-saturation,1.1));backdrop-filter:blur(var(--glass-blur,12px)) saturate(var(--glass-saturation,1.1));box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--contrast-foreground,var(--foreground)) 10%,transparent),0 6px 22px -10px #0007}
:root:not(.dark) [data-chat-column][data-tokpanel="1"] :is([data-tokpanel-card],[data-tokpanel-agents]){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--contrast-foreground,var(--foreground)) 10%,transparent)}
[data-chat-column][data-tokpanel="1"] [data-tokpanel-card]{order:2}
[data-chat-column][data-tokpanel="1"] [data-tokpanel-agents]{order:3}

[data-tokpanel-card]{
button{margin:0;padding:0;border:0;border-radius:6px;background:none;font:inherit;color:inherit;text-align:start;cursor:pointer}
button:focus-visible{outline:2px solid var(--ring);outline-offset:1px}
[data-tp-toggle]{position:relative;display:flex;align-items:center;gap:8px;box-sizing:border-box;width:calc(100% + 8px);height:18px;margin:0 -4px;padding:0 4px}
[data-tp-toggle]:hover{background:color-mix(in srgb,var(--foreground) 6%,transparent)}
[data-tp-head]{display:flex;align-items:center;gap:8px;height:18px}
[data-tp-sec="tokens"]>[data-tp-toggle]{height:20px}
[data-tp-chev]{position:absolute;left:-7px;top:0;display:flex;align-items:center;justify-content:center;width:12px;height:100%;color:var(--tk-muted);font-size:13px;line-height:1;transition:transform .15s}
[aria-expanded="true"]>[data-tp-chev]{transform:rotate(90deg)}
[data-tp-label]{flex:none;color:var(--tk-fg);white-space:nowrap}
[data-tp-sec="tokens"] [data-tp-label]{text-transform:uppercase}
[data-tp-hv]{flex:0 1 auto;min-width:0;margin-left:auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:end;font-weight:500;color:var(--tk-fg)}
[data-tp-hv][data-tone]{color:var(--tk-tone)}
[data-tp-pill]{flex:none;box-sizing:border-box;min-width:50px;height:16px;padding:0 6px;border-radius:8px;margin-left:auto;background:var(--tk-pillc);color:var(--tk-warn);font-weight:500;font-size:12px;line-height:16px;text-align:center}
[data-tp-hv] + [data-tp-pill]{margin-left:0}
[data-tp-sec]:not(:first-child),[data-tp-grp="last"]{margin-top:3px;padding-top:3px;border-top:1px solid var(--tk-line)}
[data-tp-grp="dist"]{padding:5px 0}
[data-tp-row]{display:flex;justify-content:space-between;align-items:center;column-gap:8px;height:18px;line-height:18px}
[data-tp-k]{flex:none;color:var(--tk-muted);white-space:nowrap}
[data-tp-v]{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:end;font-weight:500;color:var(--tk-fg)}
[data-tp-row="total"]>[data-tp-v],[data-tp-row="sub-tokens"]>[data-tp-v],[data-tp-row="summary"]>[data-tp-v]{color:var(--tk-strong)}
[data-tp-row="cost"]>[data-tp-v],[data-tp-row="sub-cost"]>[data-tp-v]{color:var(--tk-accent)}
[data-tp-row="saved"]>[data-tp-v]{color:var(--tk-ok)}
[data-tp-row="comp"]>[data-tp-k]{color:var(--tk-fg)}
[data-tp-row="compact"],[data-tp-note]{height:16px;line-height:16px}
[data-tp-note]{color:var(--tk-muted)}
[data-tp-bar="seg"],[data-tp-bar="ctx"]{position:relative;display:flex;height:5px;margin:4px 0;border-radius:3px;background:var(--tk-track)}
[data-tp-bar="seg"]{overflow:hidden}
[data-tp-seg]{flex:0 0 calc(var(--f,0)*100%);min-width:0;transition:flex-basis .5s ease}
[data-tp-seg="in"]{background:var(--tk-in)}
[data-tp-seg="cr"]{background:var(--tk-cr)}
[data-tp-seg="cw"]{background:var(--tk-cw)}
[data-tp-seg="out"]{background:var(--tk-out)}
[data-tp-bar="ctx"]>[data-tp-fill]{flex:none;width:calc(min(max(var(--f,0),0),1)*100%);border-radius:3px 0 0 3px;background:var(--tk-tone);transition:width .5s ease}
[data-tp-tick]{position:absolute;top:-2px;left:calc(var(--tick,0)*100% - .5px);width:1px;height:9px;background:var(--tk-tick)}
[data-tp-legend]>[data-tp-row]{position:relative;height:16px;line-height:16px;padding-left:13px}
[data-tp-legend]>[data-tp-row]::before{content:"";position:absolute;left:0;top:5px;width:6px;height:6px;border-radius:50%;background:var(--dot)}
[data-tp-legend]>[data-k="in"]{--dot:var(--tk-in)}
[data-tp-legend]>[data-k="cr"]{--dot:var(--tk-cr)}
[data-tp-legend]>[data-k="cw"]{--dot:var(--tk-cw)}
[data-tp-legend]>[data-k="out"]{--dot:var(--tk-out)}
[data-tp-short]{display:none}
[data-tp-row="rl5"],[data-tp-row="rlw"]{display:grid;grid-template-columns:64px minmax(0,1fr) 126px;column-gap:0}
[data-tp-bar="rl"]{position:relative;height:5px;border-radius:3px;background:var(--tk-track);overflow:hidden}
[data-tp-bar="rl"]>[data-tp-fill]{display:block;height:100%;width:calc(min(max(var(--f,0),0),1)*100%);background:var(--tk-ok);transition:width .5s ease}
[data-tp-bar="rl"][data-lv="warn"]>[data-tp-fill]{background:var(--tk-warn)}
[data-tp-bar="rl"][data-lv="bad"]>[data-tp-fill]{background:var(--tk-bad)}}
[data-tokpanel-card] [data-tp-tier="c"],[data-tokpanel-card] [data-tp-tier="t"]{display:none}
@media (max-height:860px){[data-tokpanel-card]{
[data-tp-tier="f"]{display:none!important}
[data-tp-grp="dist"]{padding:3px 0}
[data-tp-grp="last"]{margin-top:4px;padding-top:0;border-top:0}
[data-tp-sec="ctx"]:not(:first-child){margin-top:2px;padding-top:2px}
[data-tp-legend]{display:grid;grid-template-columns:1fr 1fr;column-gap:8px}
[data-tp-legend]>[data-tp-row]{display:flex;justify-content:flex-start;column-gap:4px;padding-left:0}
[data-tp-legend]>[data-tp-row]::before{display:none}
[data-tp-legend]>[data-tp-row]>*{flex:none;overflow:visible;color:inherit}
[data-tp-legend]>:nth-child(odd){color:var(--tk-muted)}
[data-tp-legend]>:nth-child(even){justify-content:flex-end;color:var(--tk-fg)}
[data-tp-long]{display:none}
[data-tp-short]{display:inline}}}
@media (min-height:641px) and (max-height:860px){[data-tokpanel-card] [data-tp-tier="c"]{display:flex}}
@media (max-height:640px){[data-tokpanel-card]{
[data-tp-tier]:not([data-tp-sec]){display:none!important}
[data-tp-sec][data-tp-tier]>:not([data-tp-toggle],[data-tp-head]){display:none!important}
[data-tp-sec="comp"]{display:none!important}
[data-tp-sec="ctx"]:not(:first-child){margin-top:0;padding-top:0;border-top:0}}}
@media (min-height:1000px){[data-tokpanel-card] [data-tp-tier="t"]{display:block}}
@media (max-height:520px){[data-chat-column][data-tokpanel="1"] [data-tokpanel-card]{display:none!important}}
@media (prefers-reduced-motion:reduce){[data-tokpanel-card]{[data-tp-chev],[data-tp-seg],[data-tp-fill]{transition:none}}}

[data-tokpanel-agents]{
button{margin:0;padding:0;border:0;border-radius:6px;background:none;font:inherit;color:inherit;text-align:start;cursor:pointer}
button:focus-visible{outline:2px solid var(--ring);outline-offset:1px}
[data-tp-toggle]{flex:none;display:grid;grid-template-columns:12px 1fr auto;width:100%}
[data-tp-chev]{color:var(--tk-muted);font-size:14px;text-align:center;transition:transform .15s}
[aria-expanded="true"]>[data-tp-chev]{transform:rotate(90deg)}
[data-tp-val]{color:var(--tk-strong);font-weight:500}
[data-tp-sub]{grid-column:2/4;color:var(--tk-muted);line-height:16px}
&[data-stale="1"] [data-tp-val]{opacity:.6}
[data-tp-body]{margin-top:6px;border-top:1px solid var(--tk-line)}
[data-tp-scope],[data-tp-note],[data-tp-more]{color:var(--tk-muted);font-size:11px;line-height:14px}
[data-tp-scope]{margin-top:5px}
[data-tp-h]{margin:7px 0 1px;font-weight:500;color:var(--tk-strong)}
[data-tp-row]{display:flex;flex-wrap:wrap;justify-content:space-between;column-gap:8px;line-height:16px}
[data-tp-row] + [data-tp-row]{margin-top:2px}
[data-tp-k]{color:var(--tk-muted)}
[data-tp-v]{flex:1 1 auto;min-width:0;text-align:end;color:var(--tk-strong)}
[data-priced="0"]>[data-tp-v]{color:var(--tk-muted);font-style:italic}
[data-tp-row="total"]{margin-top:4px!important;padding-top:3px;border-top:1px solid var(--tk-line);font-weight:500}
[data-tp-row="total"]>*{color:var(--tk-accent)}
[data-tp-note]{margin-top:3px}
ul{list-style:none;margin:0;padding:0}
[data-tp-node-toggle],[data-tp-node-head]{display:grid;grid-template-columns:12px minmax(0,1fr) auto;grid-template-areas:"c p v" ". m t";column-gap:4px;width:100%;padding:2px 0}
[data-tp-node-toggle]:hover{background:color-mix(in srgb,var(--foreground) 6%,transparent)}
[data-tp-node] [data-tp-chev]{grid-area:c;align-self:start;height:16px;line-height:16px}
[data-tp-purpose]{grid-area:p;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;color:var(--tk-strong);line-height:16px}
[aria-expanded="true"]>[data-tp-purpose]{white-space:normal;overflow-wrap:anywhere}
[data-tp-cost]{grid-area:v;text-align:end;color:var(--tk-accent);line-height:16px}
[data-tp-models]{grid-area:m;justify-self:start;max-width:100%;box-sizing:border-box;margin-top:1px;padding:0 5px;border-radius:5px;background:color-mix(in srgb,var(--foreground) 9%,transparent);color:var(--tk-fg);font-size:10.5px;line-height:15px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
[data-tp-tok]{grid-area:t;align-self:end;text-align:end;color:var(--tk-muted);font-size:11px;line-height:15px}
[data-kind="root"]>*>[data-tp-purpose]{font-weight:500}
[data-kind="workflow"]>*>[data-tp-purpose]{color:var(--tk-fg);font-style:italic}
[data-kind="workflow"]>*>[data-tp-models]{display:none}
[data-kind="child-thread"]>*>[data-tp-models]{background:color-mix(in srgb,var(--tk-cw) 18%,transparent)}
[data-missing="1"]>*>:is([data-tp-purpose],[data-tp-cost]){opacity:.55}
[data-tp-node][data-partial="1"]>*>[data-tp-tok]::before{content:"parcial";margin-right:5px;padding:0 5px;border-radius:7px;background:var(--tk-pillc);color:var(--tk-fg);font-size:10px;line-height:14px;font-weight:400;font-style:normal}
[data-tp-node][data-priced="0"]>*>[data-tp-cost]{color:var(--tk-muted);font-style:italic}
[data-tp-split]{margin:1px 0 3px 16px;font-size:11px}
:is([data-tp-row="model"],[data-tp-row="node-model"]){display:block;text-align:start;text-wrap:pretty}
:is([data-tp-row="model"],[data-tp-row="node-model"])>*{margin-right:5px;text-align:start}
[data-tp-row="model"]>[data-tp-k]{color:var(--tk-strong);font-weight:500}
[data-tp-row="model"]>[data-tp-v]{color:var(--tk-fg)}
[data-tp-row="node-model"]{line-height:15px}
[data-tp-split]>:only-child>[data-tp-k]{display:none}
[data-tp-children]{margin-left:5px}
[data-tp-children]>li{position:relative;padding-left:9px}
[data-tp-children]>li::before,[data-tp-children]>li::after{content:"";position:absolute;left:0;width:6px;border:0 solid var(--tk-track)}
[data-tp-children]>li::before{top:0;bottom:0;border-left-width:1px}
[data-tp-children]>li:last-child::before{bottom:auto;height:10px}
[data-tp-children]>li::after{top:10px;border-top-width:1px}
[data-depth="3"] [data-tp-children]>li{padding-left:6px}
[data-depth="3"] [data-tp-children]>li::after{width:4px}
[data-tp-more]{margin:1px 0 2px 14px;padding:0 4px}
[data-tp-more]:hover{color:var(--tk-fg);text-decoration:underline}}
@media (max-height:860px){[data-tokpanel-agents]{[data-tp-scope]{margin-top:3px}[data-tp-h]{margin-top:5px}[data-tp-node-toggle],[data-tp-node-head]{padding:1px 0}}}
@media (max-height:640px){[data-chat-column][data-tokpanel="1"] [data-tokpanel-agents]{display:none!important}}
@media (prefers-reduced-motion:reduce){[data-tokpanel-agents] [data-tp-chev]{transition:none}}
